{
  "summary": "As a married first‑timer couple, you may be eligible for several priority schemes such as the Married Child Priority, Elderly Priority, and the Singaporean Citizen (SC) Priority, but many schemes target specific circumstances you do not meet. The main priority you can consider is the Married Child Priority if you have or plan to have children in the future, otherwise you will participate in the standard BTO ballot.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "First‑timer couples who are married Singapore Citizens are automatically eligible for the standard BTO ballot without any special priority scheme.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "The Married Child Priority scheme gives priority to first‑timer families who have at least one married child who is a Singapore Citizen and is at least 21 years old, which does not apply to you as you have no children.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "The Elderly Priority scheme applies to first‑timer households where the applicant(s) are 55 years old or older, which does not apply to you.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "policy_fact",
      "text": "The Singaporean Citizen (SC) Priority scheme gives priority to households where at least one applicant is a Singapore Citizen and the other is a Singapore Permanent Resident; it does not apply to couples where both are Singapore Citizens.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "policy_fact",
      "text": "The Family Nucleus Priority scheme is for families with at least one child under 21 years old, which does not apply to you.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c6",
      "kind": "caveat",
      "text": "Priority scheme eligibility can change with each BTO launch, so you should verify the current list of schemes on the HDB website before each application.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Prepare identity documents, income proof, CPF statements, self‑employment records, and any property or loan intent documents for the HFE application.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "For the HFE application, Singapore Citizens must submit their NRIC (original and photocopy).",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "Recent CPF contribution statements (last 3 months) are required for salaried employees.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "Self‑employed applicants need to provide the latest Income Tax Notice of Assessment (NOA) and a declaration of self‑employment income for the past 12 months.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "policy_fact",
      "text": "A recent payslip (last 1 month) or an employment letter confirming salary is required for each salaried applicant.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "policy_fact",
      "text": "If either applicant owns any private property or has an existing housing loan, the relevant title deed or loan statement must be submitted.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "Gather original NRICs and make clear photocopies for both applicants.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c7",
      "kind": "preparation_step",
      "text": "Print the latest CPF contribution statements for Jia Hui (last 3 months).",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c8",
      "kind": "preparation_step",
      "text": "Obtain Ken's latest Income Tax Notice of Assessment and prepare a self‑employment income declaration covering the past year.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c9",
      "kind": "preparation_step",
      "text": "If either of you holds any private property, collect the title deed or sale and purchase agreement; if you have a housing loan, get the latest loan statement.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c10",
      "kind": "caveat",
      "text": "Exact document requirements may vary slightly depending on HDB's latest guidelines; please verify the checklist on the HDB website before submission.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "private_property_interest",
      "needed_for": ["hfe_documents"],
      "follow_up_question": "Do either of you currently own or have an interest in any private property?"
    },
    {
      "field": "housing_loan_intent",
      "needed_for": ["hfe_documents"],
      "follow_up_question": "Are you planning to take a housing loan for the BTO flat?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "If you receive a queue number but choose not to book any of the remaining flats, you will forfeit the queue number and will have to wait for the next BTO exercise. You may also be barred from applying for the next few BTO exercises depending on HDB's rules.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "If a first-timer couple declines to book any of the flats offered after receiving a queue number, the queue number is forfeited and the couple loses the right to that flat.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "HDB may impose a waiting period (typically 1 to 2 BTO exercises) before the couple can apply for another BTO flat after forfeiting a queue number.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "If you are unsure about the remaining flats, consider reviewing the floor plans, location, and resale value before the booking deadline to avoid forfeiture.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "caveat",
      "text": "Exact waiting periods and penalties can vary; please verify the latest rules on the HDB website or the HDB Flat Portal.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "You can withdraw your BTO application before the ballot results are released without incurring any penalty. Submit a withdrawal request through the HDB portal or contact HDB as soon as possible.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "First-timer couples may withdraw a BTO application before the ballot results are announced without any penalty.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "Log in to the HDB Flat Portal and submit a withdrawal request for your BTO application.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "If you cannot withdraw online, contact HDB's Customer Service Centre by phone or email to confirm the withdrawal.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "caveat",
      "text": "If the ballot results have already been released, withdrawal may be subject to different rules and possible penalties; verify the status before proceeding.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "As a first‑timer couple with one Singapore citizen, you can apply for a BTO flat under the first‑timer scheme. You need to obtain an HFE letter and gather the required documents before submitting your application.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "A first‑timer couple is defined as a married or engaged pair where neither applicant has previously owned a HDB flat or private property, and at least one applicant is a Singapore citizen.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "With one Singapore citizen (Kumar) and one non‑resident work pass holder (Ana), the couple meets the citizenship requirement for a first‑timer BTO application.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "First‑timer couples can apply for new BTO flats in the standard BTO ballot, subject to availability and eligibility criteria.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Apply for a HDB Flat Eligibility (HFE) letter before the BTO ballot opens; the HFE letter is required to submit a BTO application.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Prepare the following documents for the HFE application: NRICs (or passport for the non‑citizen), Work Pass details, recent income documents (e.g., payslips or CPF statements), and a declaration of no prior flat ownership.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "If you intend to take an HDB loan, decide on the loan amount and gather supporting documents such as CPF contribution history and employment letters.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c7",
      "kind": "caveat",
      "text": "Exact document requirements and processing times may vary; please verify the latest checklist on the HDB website (https://www.hdb.gov.sg) or the HDB Flat Portal.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "applicant_2.employment",
      "needed_for": ["hfe_process"],
      "follow_up_question": "What type of Work Pass does Ana hold (e.g., Employment Pass, S Pass)?"
    },
    {
      "field": "housing_loan_intent",
      "needed_for": ["hfe_grant_loan_context"],
      "follow_up_question": "Do you plan to apply for an HDB loan, a bank loan, or are you unsure at this stage?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "The HFE letter is generally valid for six months from its issue date, so you need to check the date on your letter to know if it’s still valid for the upcoming launch.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "An HFE (Housing Flat Eligibility) letter is typically valid for six months from the date it is issued.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "Check the issue date printed on your HFE letter and compare it to the launch date you intend to apply for.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "caveat",
      "text": "If the six‑month validity period has passed, you will need to apply for a new HFE letter before the next launch.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "hfe_issue_date",
      "needed_for": ["hfe_process"],
      "follow_up_question": "What is the issue date printed on your HFE letter?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Start by applying for your HFE (HDB Flat Eligibility) letter, then gather the required documents and prepare your BTO application before the launch.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "preparation_step",
      "text": "Apply for an HFE (HDB Flat Eligibility) letter through the HDB e-Services portal as soon as possible, since the letter is required to submit a BTO application.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "Ensure both applicants are Singapore Citizens, are first‑timer couples (married or engaged), and meet the minimum age requirement of 21 years.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Gather the documents needed for the HFE application, such as NRICs, proof of citizenship, and any documents related to prior HDB flat ownership or subsidies (if applicable).",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Check the validity period of the HFE letter (typically 6 months) and note the issue date so you can submit the BTO application within that window.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Once you have the HFE letter, log in to the HDB Flat Portal during the BTO launch window, select your preferred flat type and location, and complete the online application.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c6",
      "kind": "caveat",
      "text": "Exact dates, document checklists, and any changes to the process may vary; please verify the latest information on the official HDB website (https://www.hdb.gov.sg) or the HDB Flat Portal (https://homes.hdb.gov.sg).",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "hfe_status",
      "needed_for": ["application_requirements"],
      "follow_up_question": "Have you already applied for or received your HFE (HDB Flat Eligibility) letter?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Both applicants should gather recent payslips, CPF contribution statements, and income tax documents to prove their employment income for the HFE application.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "preparation_step",
      "text": "Obtain the most recent three months of payslips from your respective employers.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "Collect your CPF contribution statements for the same three‑month period to verify CPF deductions.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Gather your latest Notice of Assessment (NOA) or Income Tax Notice from IRAS to confirm annual taxable income.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "If you receive any additional income (e.g., bonuses, commissions, or part‑time work), bring supporting documents such as bonus letters or contract statements.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "caveat",
      "text": "The exact list of required income documents may be updated by HDB; verify the current checklist on the HDB website or the HDB Flat Portal before submission.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "First‑timer couples who are both Singapore Citizens and have not owned a flat or received a housing subsidy are eligible for the first‑timer priority scheme. You may apply for priority, but the final allocation depends on HDB’s assessment and availability.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "First‑timer priority is available to married couples where both applicants are Singapore Citizens and have never owned a HDB flat or received any HDB housing subsidy.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "Having no children does not affect eligibility for first‑timer priority.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Obtain an HFE (Housing Flat Eligibility) letter confirming your first‑timer status before submitting the BTO application.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "When applying, indicate that you are a first‑timer couple to be considered for the priority allocation.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "caveat",
      "text": "Priority does not guarantee a flat; allocation still depends on ballot results, flat availability, and HDB’s final assessment.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "First‑timer couples must confirm both partners meet the citizenship, age and prior‑flat criteria, obtain an HFE letter, and gather the required documents before applying.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "At least one applicant in a first‑timer couple must be a Singapore citizen, and the other must be a Singapore citizen or Singapore permanent resident.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "Both applicants must be at least 21 years old on the date of application.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "First‑timer couples must not have previously owned any HDB flat or private residential property, nor have received any HDB subsidy.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Apply for a HDB Flat Eligibility (HFE) letter online via the HDB portal before the BTO ballot opens.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Prepare the required documents for the HFE application, such as NRICs, birth certificates, marriage certificate, and income documents if a loan is intended.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c6",
      "kind": "policy_fact",
      "text": "The HFE letter is valid for 6 months from the issue date for the purpose of applying to a BTO project.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c7",
      "kind": "policy_fact",
      "text": "The HFE letter is needed to determine eligibility for HDB grants and HDB housing loans, though the exact grant amounts are calculated later.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c8",
      "kind": "preparation_step",
      "text": "Check the specific BTO project’s eligibility criteria (e.g., location, flat type) once the ballot opens.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c9",
      "kind": "caveat",
      "text": "If the non‑resident spouse does not hold Singapore PR status, the couple may be ineligible; please verify the spouse’s residency status on the HDB website.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "applicant_2.citizenship",
      "needed_for": ["policy_fact:c1"],
      "follow_up_question": "Is Maria a Singapore Permanent Resident or does she hold any other Singapore residency status?"
    },
    {
      "field": "applicant_2.age",
      "needed_for": ["policy_fact:c2"],
      "follow_up_question": "How old is Maria?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Yes, you can use your HFE letter for the December launch as it is still within its typical validity period. Ensure you submit your application before the letter expires.",
  "claims": [
    {
      "claim_id": "c1",
      "text": "An HFE letter is generally valid for 12 months from the date of issue.",
      "kind": "policy_fact",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "text": "Your HFE letter was issued on 20 February 2026, so it will remain valid through December 2026.",
      "kind": "policy_fact",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "text": "Submit your BTO application before the HFE letter expires to avoid needing a new letter.",
      "kind": "preparation_step",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "text": "If you are unsure about the exact expiry date, verify the validity period on the HFE letter or the HDB portal.",
      "kind": "caveat",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "If your HFE letter has expired before the BTO ballot results are released, the application may be considered invalid and could be cancelled. You should obtain a new HFE letter as soon as possible.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "An HFE letter for first‑timer couples is typically valid for six months from the issue date.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "If the HFE letter expires before the BTO ballot results are announced, the application may be deemed ineligible and could be cancelled.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Contact HDB promptly to request a fresh HFE letter if your current one has expired.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "caveat",
      "text": "Exact handling of an expired HFE letter may vary; please verify the latest guidance on the HDB website or the HDB Flat Portal.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "If you do not book a flat in the BTO exercise, you will receive a non‑selection count, which may affect your eligibility for future BTO exercises. You should check the HDB portal for the exact count and any waiting periods that apply.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "Couples who are invited to a BTO exercise but do not select a flat receive a non‑selection count.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "A non‑selection count may restrict the couple from participating in the next one or two BTO exercises, depending on HDB's rules at the time.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Log in to the HDB Flat Portal to view your non‑selection count and any associated waiting period.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "caveat",
      "text": "The exact impact of a non‑selection count (e.g., number of future exercises you may miss) can change, so verify the current policy on the HDB website.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Because Raymond previously owned an HDB flat, the couple is not considered a first‑timer household for priority considerations; they will be treated as a second‑timer household.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "A household is classified as a first‑timer only if none of the applicants have previously owned or sold an HDB flat, or received a subsidised resale flat.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "Since Raymond previously bought and sold an HDB flat, he is not a first‑timer applicant.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "A couple where at least one applicant is not a first‑timer is treated as a second‑timer household for priority and eligibility purposes.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Proceed with the standard HFE (HDB Flat Eligibility) application for a second‑timer household and ensure Raymond provides documentation of his previous flat ownership and sale.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "caveat",
      "text": "Specific priority schemes may have additional criteria; verify the latest HDB guidelines on the HDB website for any nuances.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "You cannot apply for a 2‑room Flexi BTO as a couple because Leila, holding a Visit Pass, is not eligible to be an applicant. Only Singapore citizens or Singapore permanent residents can apply, and you will need to obtain a HFE letter before applying.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "For a BTO application, each applicant must be a Singapore citizen or a Singapore permanent resident; holders of a Visit Pass are not eligible to be applicants.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "At least one applicant in a first‑timer couple must be a Singapore citizen, and the other applicant may be a Singapore citizen or a Singapore permanent resident.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "If Leila obtains Singapore permanent residency, you can then proceed to apply as a married couple.",
